"use client";

import { useState, useEffect } from "react";
import { getAuth, signInWithPopup, signInWithRedirect, getRedirectResult, GoogleAuthProvider } from "firebase/auth";
import { app } from "@/lib/firebase";
import { Capacitor, registerPlugin } from "@capacitor/core";
import axios from "axios";
import { API_BASE } from "@/lib/api";
import { Loader2 } from "lucide-react";
import { getAndClearReturnUrl } from "@/lib/returnUrl";

// Native Capacitor FirebaseAuthentication bridge
const getNativeAuthPlugin = () => {
  if (typeof window !== 'undefined' && (window as any)?.Capacitor?.Plugins?.FirebaseAuthentication) {
    return (window as any).Capacitor.Plugins.FirebaseAuthentication;
  }
  return registerPlugin<any>('FirebaseAuthentication');
};

interface GoogleAuthButtonProps {
  referralCode?: string;
  onSuccess?: () => void;
  onError?: (error: string) => void;
  buttonText?: string;
}

export function GoogleAuthButton({ referralCode = "", onSuccess, onError, buttonText = "Continue with Google" }: GoogleAuthButtonProps) {
  const [loading, setLoading] = useState(false);

  // Handle redirect result on mobile web browsers returning from Google account selection
  useEffect(() => {
    if (!app || typeof window === 'undefined') return;
    if (Capacitor.isNativePlatform()) return;

    try {
      const auth = getAuth(app);
      getRedirectResult(auth).then(async (result) => {
        if (result && result.user) {
          setLoading(true);
          const idToken = await result.user.getIdToken();
          if (idToken) {
            try {
              localStorage.removeItem('accessToken');
              localStorage.removeItem('refreshToken');
            } catch {}

            try {
              const csrfRes = await axios.get(`${API_BASE}/auth/csrf-token`, { withCredentials: true });
              if (csrfRes.data?.csrfToken && typeof window !== 'undefined') {
                (window as any).__trayago_csrf = csrfRes.data.csrfToken;
              }
            } catch {}

            const res = await axios.post(`${API_BASE}/auth/google-login`, {
              idToken,
              referralCode,
            }, { withCredentials: true });

            if (res.data.success) {
              localStorage.setItem("user", JSON.stringify(res.data.data));
              if (res.data.accessToken) localStorage.setItem("accessToken", res.data.accessToken);
              if (res.data.refreshToken) localStorage.setItem("refreshToken", res.data.refreshToken);
              if (onSuccess) {
                onSuccess();
              } else {
                window.location.href = getAndClearReturnUrl();
              }
            }
          }
        }
      }).catch((err) => {
        console.warn('[GoogleAuth] getRedirectResult check:', err?.message);
      }).finally(() => {
        setLoading(false);
      });
    } catch {}
  }, [onSuccess, referralCode]);

  const handleGoogleLogin = async () => {
    setLoading(true);
    try {
      try {
        localStorage.removeItem('accessToken');
        localStorage.removeItem('refreshToken');
      } catch {}

      let idToken: string | undefined;

      const isNative = typeof window !== 'undefined' && Capacitor.isNativePlatform();

      if (isNative) {
        // Native Android / iOS Google Sign-In via native Capacitor plugin bridge
        const nativeAuth = getNativeAuthPlugin();
        const signInResult = await nativeAuth.signInWithGoogle();
        const tokenRes = await nativeAuth.getIdToken();
        idToken = tokenRes?.token || signInResult?.credential?.idToken;
        if (!idToken) {
          throw new Error("Failed to acquire authentication token from Google.");
        }
      } else {
        // Desktop / Web browser Google Sign-In via standard Firebase popup
        if (!app) {
          onError?.("Firebase is not properly initialized. Please check your configuration.");
          setLoading(false);
          return;
        }
        const auth = getAuth(app);
        const provider = new GoogleAuthProvider();
        provider.setCustomParameters({ prompt: 'select_account' });

        try {
          const result = await signInWithPopup(auth, provider);
          idToken = await result.user.getIdToken();
        } catch (popupErr: any) {
          // Fall back to redirect if popup is blocked on mobile browsers
          if (
            popupErr?.code === 'auth/popup-blocked' ||
            popupErr?.code === 'auth/cancelled-popup-request' ||
            popupErr?.message?.includes('popup')
          ) {
            console.log('[GoogleAuth] Popup blocked on mobile, redirecting to Google...');
            await signInWithRedirect(auth, provider);
            return;
          }
          throw popupErr;
        }
      }

      if (!idToken) {
        throw new Error("No authentication token available.");
      }

      // Pre-fetch a CSRF token by hitting a safe GET endpoint first
      try {
        const csrfRes = await axios.get(`${API_BASE}/auth/csrf-token`, { withCredentials: true });
        if (csrfRes.data?.csrfToken && typeof window !== 'undefined') {
          (window as any).__trayago_csrf = csrfRes.data.csrfToken;
        }
      } catch (e) {
        // Fallback to /auth/status
        try { await axios.get(`${API_BASE}/auth/status`, { withCredentials: true }); } catch {}
      }

      const res = await axios.post(`${API_BASE}/auth/google-login`, {
        idToken,
        referralCode,
      }, { withCredentials: true });

      if (res.data.success) {
        localStorage.setItem("user", JSON.stringify(res.data.data));
        if (res.data.accessToken) {
          localStorage.setItem("accessToken", res.data.accessToken);
        }
        if (res.data.refreshToken) {
          localStorage.setItem("refreshToken", res.data.refreshToken);
        }
        if (onSuccess) {
          onSuccess();
        } else {
          window.location.href = getAndClearReturnUrl();
        }
      }
    } catch (err: any) {
      const errMsg = err?.message || String(err || "");
      if (
        err?.code === 'auth/popup-closed-by-user' ||
        err?.code === 'auth/cancelled-popup-request' ||
        errMsg.toLowerCase().includes('cancel') ||
        errMsg.toLowerCase().includes('closed by user') ||
        errMsg.includes('12501') ||
        errMsg.includes('16')
      ) {
        onError?.("Google sign-in was cancelled.");
      } else {
        onError?.(err?.response?.data?.error || err?.response?.data?.message || err?.message || "Google sign-in failed");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <button
      type="button"
      onClick={handleGoogleLogin}
      disabled={loading}
      className="w-full py-3 mt-4 bg-white hover:bg-gray-50 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-gray-200 border border-gray-300 text-gray-800 font-semibold rounded-xl flex items-center justify-center gap-3 transition-all shadow-sm active:scale-95 dark:bg-[#1A1C20] dark:border-[#2C2E33] dark:text-gray-100 dark:hover:bg-[#25272B] dark:focus-visible:ring-[#3D3F45]"
    >
      {loading ? (
        <Loader2 className="w-5 h-5 animate-spin" />
      ) : (
        <>
          <svg className="w-5 h-5" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
            <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
            <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
            <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
            <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
          </svg>
          {buttonText}
        </>
      )}
    </button>
  );
}

